const ABANDON_HOURS = 48; // judgment call, see trigger node's own notes
const now = new Date();

function asArray(item) {
  const json = item.json;
  if (Array.isArray(json)) return json;
  if (json && json.data && Array.isArray(json.data.opportunities)) return json.data.opportunities;
  if (json && Array.isArray(json.opportunities)) return json.opportunities;
  return [];
}

const abandoned = $input.all().flatMap(asArray).filter((opp) => {
  if (!opp.proposalViewedAt) return false; // never opened - not abandonment, just not viewed yet
  if (opp.abandonmentFollowupSentAt) return false; // already followed up once - single-shot, not a repeating cadence
  const hoursSinceViewed = (now - new Date(opp.proposalViewedAt)) / 3600000;
  return hoursSinceViewed >= ABANDON_HOURS;
});

return abandoned.map((opp) => ({ json: opp }));

const body = $input.first().json;
const textBlock = (body.content || []).find((b) => b.type === 'text');
if (!textBlock) throw new Error('Claude response had no text content block.');
return [{ json: { draftText: textBlock.text } }];
